/* Browser-only interaction prototype. Never sends photos or personal settings to a server. */
(() => {
  'use strict';
  const $=id=>document.getElementById(id), E=window.ShiweiEngine, recipes=window.RECIPES;
  const escape=text=>String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const STORAGE='shiwei-demo-v1';
  const defaultProfile={allergies:'',others:'',seasonings:['食用油','盐','生抽','醋','大蒜','姜','葱'],flavor:'不限',goal:'日常均衡',conditions:[],loggedIn:false,seasoningMode:'ignore'};
  let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE)||'{}')||{};}catch{}
  const profile={...defaultProfile,...(saved.profile&&typeof saved.profile==='object'?saved.profile:{})};
  for(const key of ['allergies','others','flavor','goal','seasoningMode'])if(typeof profile[key]!=='string')profile[key]=defaultProfile[key];
  profile.seasonings=Array.isArray(profile.seasonings)?profile.seasonings.filter(x=>SEASONINGS.includes(x)):[...defaultProfile.seasonings];
  profile.conditions=Array.isArray(profile.conditions)?profile.conditions.filter(x=>typeof x==='string'):[];
  const state={ingredients:[],servings:1,flavor:profile.flavor,seasoningMode:profile.seasoningMode,includeOthers:false,mode:'meal',health:false,conditions:[...profile.conditions],allowBuy:false,generated:false,busy:false,iteration:0,page:0,meal:[],target:null,requested:3,custom:false,favorites:Array.isArray(saved.favorites)?saved.favorites.filter(x=>recipes.some(r=>r.id===x)):[],photoUrl:null,demoConflict:false};
  let pendingConditions=[],pendingMatch=[],lastModal='',toastTimer,revision=0;
  const knownConditions=['高血压','糖尿病','痛风'];
  function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({profile,favorites:state.favorites}));}catch{toast('当前浏览器无法保存设置，本次仍可继续体验');}}
  function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
  function config(){return {ingredients:state.ingredients.map(i=>({...i})),servings:state.servings,flavor:state.flavor,seasoningMode:state.seasoningMode,seasonings:[...profile.seasonings],allergies:profile.allergies,others:profile.others,includeOthers:state.includeOthers,health:state.health,allowBuy:state.allowBuy,goal:profile.goal};}
  function dirty(){revision++;const had=state.generated;state.generated=false;state.busy=false;state.page=0;state.meal=[];if(had)toast('条件已更新，确认后重新搭配');renderResults();renderHealth();}
  function syncSettings(){ $('servings').value=state.servings;$('quick-allergies').value=profile.allergies;$('include-others').checked=state.includeOthers;$('others-summary').textContent=profile.others?`已保存的附加限制：${profile.others}`:'尚未设置他人过敏忌口';document.querySelectorAll('[name="seasoning-mode"]').forEach(x=>x.checked=x.value===state.seasoningMode);$('seasoning-checks').innerHTML=SEASONINGS.map(s=>`<label class="check-chip"><input type="checkbox" data-seasoning="${escape(s)}" ${profile.seasonings.includes(s)?'checked':''}>${escape(s)}</label>`).join('');$('seasoning-checks').hidden=state.seasoningMode!=='check';renderFlavors();renderHealth();}
  function renderFlavors(){ $('input-flavors').innerHTML=['不限','清淡','微辣','浓香'].map(f=>`<button class="flavor-button ${state.flavor===f?'active':''}" data-flavor="${f}" aria-pressed="${state.flavor===f}">${f}</button>`).join('');}
  function renderIngredients(){ $('ingredient-count').textContent=`${state.ingredients.length} 种`;$('ingredient-list').innerHTML=state.ingredients.length?state.ingredients.map((x,i)=>`<div class="ingredient-row"><span class="ingredient-emoji" aria-hidden="true">${INGREDIENT_EMOJI[E.normalize(x.name)]||'🌿'}</span><input aria-label="食材${i+1}名称" data-ingredient-name="${i}" value="${escape(x.name)}" maxlength="20"><input class="amount" aria-label="${escape(x.name)}用量" data-ingredient-amount="${i}" placeholder="用量选填" value="${escape(x.amount)}" maxlength="20"><button class="remove-ingredient" data-remove="${i}" aria-label="删除${escape(x.name)}">×</button></div>`).join(''):'<div class="ingredient-empty">还没有食材，拍张照或手动添加吧</div>';$('ingredient-confirm').hidden=!state.ingredients.length;}
  function renderHealth(){ $('health-switch').classList.toggle('on',state.health);$('health-entry').setAttribute('aria-pressed',String(state.health));$('health-status').textContent=state.health?`演示模式 · ${state.conditions.join('、')||'待设置'}`:'按需开启，照顾你的饮食限制';$('health-summary').hidden=!state.health;$('health-summary').innerHTML=`♡ 健康筛选演示：${escape(state.conditions.join('、')||'待设置')}<br>依据与营养均为模拟，不代表实际健康适宜性。 <button data-action="health">修改</button>`;}
  function cardImage(r){if(r.type==='meat')return 'assets/meat.png';if(r.type==='soup')return 'assets/meal.png';if(['tomato-eggs','carrot-eggs','shakshuka','pasta'].includes(r.id))return 'assets/meal.png';return 'assets/veg.png';}
  const category=r=>({meat:'荤菜',veg:'素菜',soup:'汤'}[r.type]);
  function recipeCard(r,{browse=false,favoriteView=false}={}){const m=E.missing(r,config()),isSaved=state.favorites.includes(r.id);return `<article class="recipe-card"><div class="recipe-cover"><img class="food-art" src="${cardImage(r)}" alt="${category(r)}餐食示意图，并非菜谱成品实拍" loading="lazy"><button class="favorite-button ${isSaved?'saved':''}" data-favorite="${r.id}" aria-label="${isSaved?'取消收藏':'收藏'}${r.name}" aria-pressed="${isSaved}">${isSaved?'♥':'♡'}</button><span class="category-label">${category(r)}${r.special?' · 风味灵感':' · 家常味道'}</span></div><div class="recipe-card-body"><h3>${r.name}</h3><div class="recipe-card-meta"><span>◷ ${r.minutes} 分钟</span><span>约 ${r.kcal} kcal / 人份</span></div><p class="ingredient-match">${m.all.length?`<em>待补：${escape(m.all.join('、'))}</em>`:`手边就有 · ${r.ingredients.map(escape).join('、')}`}</p>${state.health?`<div class="card-nutrition"><span>蛋白质 ${r.protein}g</span><span>脂肪 ${r.fat}g</span><span>碳水 ${r.carbs}g</span></div><div class="subtle">营养及筛选为模拟示意</div>`:''}<div class="recipe-card-actions">${!browse&&!favoriteView?`<button data-replace="${r.id}">↻ 换一道</button>`:`<span class="subtle">${r.flavors.join(' / ')}</span>`}<button data-detail="${r.id}">查看做法 ↗</button></div></div></article>`;}
  function healthBlock(){if(!state.health)return null;if(!state.conditions.length)return {title:'先确认本次健康模式的疾病信息',body:'选择或输入名称，确认后再继续模拟健康筛选。'};const unsupported=state.conditions.filter(x=>!knownConditions.includes(x));if(unsupported.length)return {title:`暂不支持：${unsupported.join('、')}`,body:'演示名录可以识别这个名称，但尚未提供对应的可靠依据。你可以修改信息，或切回普通推荐；过敏与明确忌口仍然生效。'};if(state.demoConflict)return {title:'当前演示规则无法同时满足',body:'此场景模拟多条规则相互冲突，已停止健康推荐。这不是关于所选疾病本身能否兼顾的医学结论。请修改条件或主动切回普通模式。'};return null;}
  function activeConstraints(){const r=E.restrictions(config());return `<div class="constraint-strip"><span>${state.servings} 人份</span><span>口味：${escape(state.flavor)}</span><span>${state.includeOthers?'本人 + 已选他人限制':'本人资料'}</span>${r.length?`<span>排除：${r.map(escape).join('、')}</span>`:'<span>未设置过敏忌口</span>'}${state.health?'<span>♡ 健康演示已开启</span>':''}</div>`;}
  function renderResults(){ $('favorite-count').textContent=state.favorites.length;$('result-meta').innerHTML='';$('result-actions').innerHTML='';$('counts-toggle').hidden=state.mode!=='meal';$('custom-counts').hidden=!state.custom||state.mode!=='meal';document.querySelectorAll('[data-mode]').forEach(b=>{const active=b.dataset.mode===state.mode;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});$('generate-button').disabled=state.busy;$('generate-button').innerHTML=state.busy?'正在搭配，请稍候…':`确认食材，${state.mode==='meal'?'搭配这一餐':'看看有哪些菜'} <span>✧</span>`;
    if(state.busy){$('result-content').innerHTML='<div class="loading-card"><span class="spinner" aria-hidden="true"></span><span>正在搭配你的食材，留一点期待…</span><span class="subtle">模拟推荐</span></div>';return;}
    if(!state.generated){$('result-content').innerHTML='<div class="empty-result"><div class="empty-plate" aria-hidden="true">🥬</div><h3>好好吃饭，从手边开始</h3><p>先确认左侧食材与偏好，<br>让我们把这一餐搭配好。</p><div class="empty-steps"><span><b>1</b>确认食材</span><span><b>2</b>搭配一餐</span><span><b>3</b>跟着做就好</span></div></div>';return;}
    const block=healthBlock();$('result-meta').innerHTML=activeConstraints();if(block){$('result-content').innerHTML=`<div class="empty-result"><div class="empty-plate" aria-hidden="true">♡</div><h3>${escape(block.title)}</h3><p>${escape(block.body)}</p><div class="inline-actions"><button class="button outline small" data-action="health">修改健康信息</button><button class="button primary small" data-action="ordinary">切回普通推荐</button></div></div>`;return;}
    const pool=E.eligible(recipes,config());const shown=state.mode==='meal'?state.meal:pool.slice(state.page*6,state.page*6+6);const totalKcal=shown.reduce((s,r)=>s+r.kcal,0);
    let notice='';if(state.mode==='meal'&&shown.length<state.requested)notice=`<div class="result-notice"><strong>先做得了的，${shown.length?`这次搭配了 ${shown.length} 道菜`:'这次还没有可做的菜'}。</strong><br>按当前食材、数量、口味和限制，暂时凑不齐 ${state.requested} 道。${!state.allowBuy?'可以补充食材，或主动接受补买。':''}<div class="inline-actions">${!state.allowBuy?'<button class="button small outline" data-action="allow-buy">接受补买，再搭配</button>':''}<button class="text-button" data-action="focus-input">修改食材 ↑</button></div></div>`;
    if(!shown.length){$('result-content').innerHTML=notice+`<div class="empty-result"><div class="empty-plate" aria-hidden="true">🌿</div><h3>换一点条件，灵感就会来</h3><p>没有符合当前全部条件的菜谱。<br>试试增加食材、调整口味或接受补买。<br>过敏与明确忌口不会被自动放宽。</p><div class="inline-actions">${!state.allowBuy?'<button class="button outline small" data-action="allow-buy">接受补买</button>':''}<button class="text-button" data-action="focus-input">修改食材 ↑</button></div></div>`;return;}
    let summary=state.mode==='meal'?`<div class="result-summary"><div><strong>${state.target?`${state.target.meat?'荤素搭配':'清爽素食'}，刚刚好的一餐`:'为你搭配的一餐'}</strong><small>共 ${shown.length} 道 · ${state.servings} 人份 · 图片为餐食示意</small></div><div class="summary-kcal"><b>${totalKcal}</b><span>kcal / 人份</span></div></div>`:`<div class="browse-controls"><span class="subtle">找到 ${pool.length} 道 · 家常菜优先，风味灵感随后</span><label class="shopping-toggle"><input type="checkbox" id="browse-buy" ${state.allowBuy?'checked':''}>接受补买</label></div>`;
    $('result-content').innerHTML=summary+notice+`<div class="recipe-grid">${shown.map(r=>recipeCard(r,{browse:state.mode==='browse'})).join('')}</div>`;
    $('result-actions').innerHTML=state.mode==='meal'?`<div class="result-footer"><p><strong>想换个搭配？再找一点新灵感。</strong>保留食材和偏好，只更新这一餐。</p><button class="button outline small" data-action="regenerate">↻ 整套重推</button></div>`:`<div class="pagination"><button data-page="prev" ${state.page===0?'disabled':''}>← 上一页</button><span>${state.page+1} / ${Math.max(1,Math.ceil(pool.length/6))}</span><button data-page="next" ${(state.page+1)*6>=pool.length?'disabled':''}>下一页 →</button></div>`;
    $('result-actions').innerHTML+=`<p class="result-bottom-note">${state.ingredients.some(x=>!E.amount(x.amount))?'食材数量未填或单位无法核对，尚未核实是否够量。 ':''}热量按模拟菜谱建议用量估算，不代表实际摄入。${state.seasoningMode==='ignore'?'未检查调味料库存，请查看做法中的调味料清单。':''}${state.health?' 健康筛选、营养与注意事项均为交互演示，不代表实际健康适宜性。':''}</p>`;
  }
  function readCounts(){const values=['meat','veg','soup'].map(t=>$('count-'+t).value);if(values.every(v=>v===''))return null;const counts=Object.fromEntries(['meat','veg','soup'].map((t,i)=>[t,values[i]===''?0:Number(values[i])]));if(Object.values(counts).some(x=>!Number.isInteger(x)||x<0)||Object.values(counts).reduce((a,b)=>a+b,0)<1||Object.values(counts).reduce((a,b)=>a+b,0)>6){toast('请指定合计1–6道菜，或全部留空自动搭配');return false;}return counts;}
  async function generate({scroll=false}={}){if(state.busy)return;state.ingredients=state.ingredients.map(x=>({...x,name:E.normalize(x.name.trim())})).filter(x=>x.name);if(!state.ingredients.length){toast('先添加至少一种食材吧');$('new-ingredient').focus();return;}const counts=state.mode==='meal'?readCounts():null;if(counts===false)return;const token=++revision;state.busy=true;state.generated=false;renderResults();await new Promise(r=>setTimeout(r,480));if(token!==revision)return;state.busy=false;state.generated=true;state.iteration++;state.page=0;if(!healthBlock()){const meal=E.buildMeal(recipes,config(),state.iteration-1,counts);state.meal=meal.selected;state.target=meal.target;state.requested=meal.total;}renderIngredients();renderResults();if(scroll)document.querySelector('.results-column').scrollIntoView({behavior:'smooth',block:'start'});}
  function modal(title,body,footer='',kind='generic'){lastModal=kind;$('modal-body').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="modal-close" data-action="close" aria-label="关闭弹窗">×</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('modal').open)$('modal').showModal();}
  function closeModal(){$('modal').close();lastModal='';}
  function openLogin(){modal('开启健康模式',`<div class="login-content"><div class="login-illustration">♡</div><h3>多一份了解，多一份照顾</h3><p>健康模式需要先登录。<br>这里使用演示账户，无需手机号或真实个人资料。</p><button class="button primary full" data-action="demo-login">使用演示账户继续 →</button><div class="modal-note">仅体验疾病输入、限制筛选和依据入口的交互。全部健康数据均为模拟，不用于真实饮食决策。</div></div>`,'','login');}
  function openHealth(){if(!profile.loggedIn){openLogin();return;}pendingConditions=[...state.conditions];pendingMatch=[];renderHealthModal();}
  function renderHealthModal(message=''){modal('这一餐，多照顾你一点',`<div class="modal-content"><div class="modal-note">健康模式演示 · 无真实医学依据或适宜性判断，请勿输入真实敏感资料。</div><h3 class="modal-section-title">选择演示疾病，或输入名称</h3><div class="condition-options">${knownConditions.map(c=>`<button class="condition-chip ${pendingConditions.includes(c)?'selected':''}" data-condition="${c}" aria-pressed="${pendingConditions.includes(c)}">${pendingConditions.includes(c)?'✓ ':''}${c}</button>`).join('')}</div><label class="field-label" for="condition-input">疾病名称 / 常用叫法</label><div class="condition-entry"><input id="condition-input" placeholder="如：高血压病、糖尿病、偏头痛" maxlength="60"><button class="button outline small" data-action="match-condition">识别名称</button></div><div id="condition-match">${message}</div><div class="field-label">本次选择（确认后应用）</div><div class="condition-options">${pendingConditions.length?pendingConditions.map(c=>`<button class="condition-chip selected" data-condition="${escape(c)}">${escape(c)} ×</button>`).join(''):'<span class="subtle">还未选择，可以选择多个</span>'}</div><p>已识别名称不等于已支持推荐。多疾病会共同约束；演示规则无法兼顾时停止推荐。</p></div>`,`<button class="button outline small" data-action="ordinary">使用普通模式</button><button class="button primary small" data-action="apply-health">确认名称并开启</button>`,'health');}
  function matchCondition(){const text=$('condition-input').value.trim();if(!text){$('condition-match').innerHTML='<p class="condition-error">请输入疾病名称，或使用上方列表。</p>';return;}const alias={'高血压病':'高血压','糖尿病症':'糖尿病','高尿酸痛风':'痛风'};const recognized=['高血压','糖尿病','痛风','偏头痛','胃炎','慢性肾病','肾病','哮喘'];pendingMatch=E.split(text).map(c=>alias[c]||c);const unknown=pendingMatch.filter(c=>!recognized.includes(c));if(unknown.length){$('condition-match').innerHTML=`<p class="condition-error">未能识别“${unknown.map(escape).join('、')}”。请检查名称、换种表述，或使用列表选择。未识别名称不会应用。</p>`;pendingMatch=[];return;}$('condition-match').innerHTML=`<div class="condition-match"><p>识别为以下名称，请核对：</p><div class="matched-condition">${pendingMatch.map(c=>`<span>${escape(c)}${knownConditions.includes(c)?'':' · 暂不支持'}</span>`).join('')}<button class="button outline small" data-action="confirm-match">确认并加入</button></div></div>`;}
  function openProfile(){modal('我的饮食设置',`<div class="modal-content"><p>仅保存在当前浏览器。默认应用本人资料，他人限制由你主动选择后合并。</p><div class="modal-note">请使用虚构资料体验，演示账户不代表真实注册或跨设备同步。</div><div class="modal-field-row"><div><label class="field-label" for="profile-allergies">本人过敏 / 明确忌口</label><input id="profile-allergies" value="${escape(profile.allergies)}" placeholder="如：花生、虾"></div><div><label class="field-label" for="profile-others">他人附加过敏 / 忌口</label><input id="profile-others" value="${escape(profile.others)}" placeholder="如：鸡蛋、鱼"></div></div><label class="field-label" for="profile-goal">饮食偏好</label><select id="profile-goal">${['日常均衡','偏清淡','偏少油'].map(g=>`<option ${profile.goal===g?'selected':''}>${g}</option>`).join('')}</select><label class="field-label" for="profile-flavor">默认口味</label><select id="profile-flavor">${['不限','清淡','微辣','浓香'].map(f=>`<option ${profile.flavor===f?'selected':''}>${f}</option>`).join('')}</select><h3 class="modal-section-title">默认调味料清单</h3><div class="check-grid">${SEASONINGS.map(s=>`<label class="check-chip"><input type="checkbox" data-profile-seasoning="${escape(s)}" ${profile.seasonings.includes(s)?'checked':''}>${escape(s)}</label>`).join('')}</div><h3 class="modal-section-title">账户与疾病资料</h3><p>${profile.loggedIn?'演示账户已登录':'当前为游客 · 普通推荐可直接使用'}<br>已保存演示疾病：${escape(profile.conditions.join('、')||'未设置')}</p><button class="text-button" data-action="health">${profile.loggedIn?'编辑疾病资料 →':'登录并体验健康模式 →'}</button></div>`,`<button class="button outline small" data-action="close">取消</button><button class="button primary small" data-action="save-profile">保存设置</button>`,'profile');}
  function saveProfile(){profile.allergies=$('profile-allergies').value.trim();profile.others=$('profile-others').value.trim();profile.goal=$('profile-goal').value;profile.flavor=$('profile-flavor').value;state.flavor=profile.flavor;profile.seasonings=[...document.querySelectorAll('[data-profile-seasoning]:checked')].map(x=>x.dataset.profileSeasoning);persist();closeModal();syncSettings();dirty();toast('已保存到当前浏览器');}
  function detail(id){const r=recipes.find(x=>x.id===id);if(!r)return;const restrictionsActive=E.isRestricted(r,config());const m=E.missing(r,config());modal(r.name,`<div class="detail-image"><img src="${cardImage(r)}" alt="餐食示意图，并非本菜品成品实拍"><span class="photo-note">餐食示意 · 模拟菜谱</span></div><div class="modal-content"><div class="detail-top"><span>${category(r)} · 约${r.minutes}分钟 · ${state.servings}人份</span><span>约 ${r.kcal} kcal / 人份</span></div><p>${r.description}</p>${restrictionsActive?'<div class="modal-note">这道收藏或旧菜谱不符合你当前的限制，当前推荐已排除它。下方内容仅供查看。</div>':''}${m.all.length?`<div class="modal-note">当前缺少：${m.all.map(escape).join('、')}。查看详情不代表已接受补买。</div>`:''}<h3 class="modal-section-title">准备这些食材</h3><div class="detail-ingredients">${r.ingredients.map(n=>{const[q,u]=E.defaultPortion(n);return `<div><span>${n}</span><span>${q*state.servings}${u}</span></div>`;}).join('')}</div><p>调味料：${r.seasonings.join('、')}（按口味适量，未作精确营养核算）</p><p class="amount-warning">以上为演示建议用量，套餐内食材可能复用；未填写或无法解析库存数量时，尚未核实是否够量。</p><h3 class="modal-section-title">一步一步，慢慢来</h3><ol class="steps">${r.steps.map(s=>`<li>${s}</li>`).join('')}</ol>${state.health?`<h3 class="modal-section-title">营养信息 · 模拟估算 / 人份</h3><div class="nutrition-grid"><div><b>${r.kcal}</b>kcal 热量</div><div><b>${r.protein}g</b>蛋白质</div><div><b>${r.fat}g</b>脂肪</div><div><b>${r.carbs}g</b>碳水</div></div><div class="modal-note">健康注意事项：此处演示与“${escape(state.conditions.join('、'))}”相关的提示位置。尚未接入或验证真实依据，不提供本菜谱适宜性的结论。<br><button class="source-link" data-action="evidence">查看依据说明 ↗</button></div>`:''}</div>`,`<button class="button outline small" data-favorite="${r.id}">${state.favorites.includes(r.id)?'♥ 已收藏，点击取消':'♡ 收藏这道菜'}</button><button class="button primary small" data-action="close">知道了，开始准备</button>`,'detail:'+id);}
  function favorites(){modal('我的收藏',`<div class="modal-content"><p>收藏保存在当前浏览器。菜谱详情会提示与当前限制的冲突，收藏不代表当前适合食用。</p>${state.favorites.length?`<div class="recipe-grid modal-recipe-grid">${state.favorites.map(id=>recipeCard(recipes.find(r=>r.id===id),{favoriteView:true})).join('')}</div>`:'<div class="favorite-empty"><div class="login-illustration">♡</div><p>还没有收藏。<br>遇到想做的菜，点一下卡片上的爱心。</p><button class="button outline small" data-action="close">去找今天的灵感</button></div>'}</div>`,'','favorites');}
  function toggleFavorite(id){if(!profile.loggedIn){modal('用演示账户收藏',`<div class="login-content"><div class="login-illustration">♡</div><h3>把喜欢的味道留下来</h3><p>登录后体验收藏。仅使用演示账户，收藏仍保存在当前浏览器。</p><button class="button primary full" data-login-favorite="${id}">演示登录并收藏</button></div>`,'','favorite-login');return;}const exists=state.favorites.includes(id);state.favorites=exists?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();renderResults();if(lastModal==='favorites')favorites();else if(lastModal==='detail:'+id)detail(id);toast(exists?'已取消收藏':'已收藏到当前浏览器');}
  function replace(id){const current=recipes.find(r=>r.id===id);if(!current)return;const others=state.meal.filter(r=>r.id!==id);const candidates=E.eligible(recipes,config()).filter(r=>r.type===current.type&&!state.meal.some(x=>x.id===r.id)&&E.fitsQuantities(r,others,config()));if(!candidates.length){toast('当前条件下没有同类替换，可以补充食材或调整口味');return;}const next=candidates[state.iteration%candidates.length];state.iteration++;state.meal=state.meal.map(r=>r.id===id?next:r);renderResults();toast(`换成了${next.name}，其余菜品保持原样`);}
  function parseText(){const text=$('ingredient-text').value.trim();if(!text){toast('先写下手边的食材');$('ingredient-text').focus();return;}const parsed=E.parseIngredients(text);for(const item of parsed){const existing=state.ingredients.find(x=>E.normalize(x.name)===item.name);if(existing){if(item.amount)existing.amount=item.amount;}else if(state.ingredients.length<24)state.ingredients.push(item);}dirty();renderIngredients();$('recognition-note').hidden=false;$('recognition-note').textContent='已按示例规则整理文字，请核对食材及用量。此处不调用真实 AI。';}
  async function handleUpload(file){if(!file)return;if(!file.type.startsWith('image/')){toast('请选择图片文件');return;}if(file.size>12*1024*1024){toast('演示支持12MB以内的图片，请换一张');return;}if(state.photoUrl)URL.revokeObjectURL(state.photoUrl);state.photoUrl=URL.createObjectURL(file);$('photo-preview').hidden=false;$('photo-preview').innerHTML=`<img src="${state.photoUrl}" alt="本次上传的食材图片预览"><span>图片仅本次使用<br>正在展示模拟识别流程…</span>`;$('recognition-note').hidden=false;$('recognition-note').textContent='图片不会上传。以下将展示固定示例识别结果，不分析你实际上传的内容。';await new Promise(r=>setTimeout(r,450));state.ingredients=EXAMPLE_INGREDIENTS.slice(0,5).map(x=>({...x}));dirty();renderIngredients();$('photo-preview').querySelector('span').innerHTML='模拟识别完成<br>请人工核对下方清单';}
  function scenario(kind){closeModal();state.busy=false;state.flavor='不限';state.allowBuy=false;state.seasoningMode='ignore';state.includeOthers=false;state.health=false;state.demoConflict=false;state.servings=1;state.mode='meal';state.custom=false;['meat','veg','soup'].forEach(t=>$('count-'+t).value='');profile.allergies='';$('recognition-note').hidden=true;state.ingredients=EXAMPLE_INGREDIENTS.map(x=>({...x}));if(kind==='recognition'){state.ingredients=[{name:'西红柿',amount:''},{name:'鸡蛋',amount:''}];$('recognition-note').hidden=false;$('recognition-note').textContent='演示：图片中另一种食材无法确认。已保留番茄与鸡蛋，可补拍、重传或手动补录，未知内容不参与推荐。';}if(kind==='shortage'){state.ingredients=[{name:'土豆',amount:'150g'}];state.custom=true;$('count-meat').value='1';$('count-veg').value='1';$('count-soup').value='1';}if(kind==='allergy'){state.ingredients=[...EXAMPLE_INGREDIENTS.map(x=>({...x})),{name:'虾',amount:''},{name:'花生',amount:''},{name:'椰奶',amount:''}];profile.allergies='鸡蛋、花生';$('recognition-note').hidden=false;$('recognition-note').textContent='过敏演示：排除鸡蛋与花生；复合调料成分无法确认的候选也会排除。规则不代表真实过敏安全认证。';}if(kind==='unsupported'||kind==='conflict'){profile.loggedIn=true;state.health=true;state.conditions=kind==='unsupported'?['偏头痛']:['高血压','糖尿病'];state.demoConflict=kind==='conflict';}syncSettings();renderIngredients();dirty();toast('已载入演示场景，不改变已保存的个人设置');if(kind==='recognition'){renderResults();document.querySelector('.ingredient-panel').scrollIntoView({behavior:'smooth',block:'start'});}else generate({scroll:true});}
  const actions={home:()=>{closeModal();window.scrollTo({top:0,behavior:'smooth'});},example:()=>{state.ingredients=EXAMPLE_INGREDIENTS.map(x=>({...x}));$('recognition-note').hidden=true;dirty();renderIngredients();toast('已填入示例食材，确认后即可搭配');},parse:parseText,generate:()=>generate({scroll:true}),regenerate:()=>generate(),health:openHealth,profile:openProfile,'save-profile':saveProfile,close:closeModal,'demo-login':()=>{profile.loggedIn=true;persist();renderHealthModal();},'match-condition':matchCondition,'confirm-match':()=>{pendingConditions=[...new Set([...pendingConditions,...pendingMatch])];pendingMatch=[];renderHealthModal();},'apply-health':()=>{if(!pendingConditions.length){toast('先选择或确认至少一个疾病名称');return;}state.conditions=[...pendingConditions];profile.conditions=[...pendingConditions];state.health=true;state.demoConflict=false;persist();closeModal();syncSettings();generate({scroll:true});},ordinary:()=>{const had=state.generated||state.health;state.health=false;state.demoConflict=false;closeModal();syncSettings();if(had&&state.ingredients.length)generate();else dirty();},favorites,'allow-buy':()=>{state.allowBuy=true;generate();},'focus-input':()=>{document.querySelector('.ingredient-panel').scrollIntoView({behavior:'smooth',block:'start'});$('new-ingredient').focus({preventScroll:true});},'custom-counts':()=>{state.custom=!state.custom;$('custom-counts').hidden=!state.custom;},'servings-up':()=>changeServings(state.servings+1),'servings-down':()=>changeServings(state.servings-1),evidence:()=>modal('健康依据说明',`<div class="modal-content"><div class="modal-note">演示占位，待验证</div><p>正式产品应在此展示每条关键健康结论对应的可靠来源，并区分：</p><ul class="evidence-list"><li>来源中的一般饮食建议</li><li>该建议与当前菜谱之间的判断过程</li><li>适用范围、限制与来源更新时间</li></ul><p>本 Demo 未接入真实文献，没有可供核验的医学结论，也不会展示虚构引用。</p></div>`,`<button class="button primary small" data-action="close">了解</button>`,'evidence'),reset:()=>modal('重新开始这次体验？',`<div class="modal-content"><p>将清除当前浏览器中的 Demo 设置、演示登录、收藏和本次食材。原始照片不会被长期保存。</p></div>`,`<button class="button outline small" data-action="close">取消</button><button class="button primary small" data-action="confirm-reset">清除并重置</button>`,'reset'),'confirm-reset':()=>{try{localStorage.removeItem(STORAGE);}catch{}if(state.photoUrl)URL.revokeObjectURL(state.photoUrl);location.reload();}};
  actions.upload=()=>$('food-upload').click();
  function changeServings(value){const n=Math.min(12,Math.max(1,Number(value)||1));if(n!==state.servings){state.servings=n;$('servings').value=n;dirty();}else $('servings').value=n;}
  document.addEventListener('click',event=>{const target=event.target.closest('button,[data-action]');if(!target||target.disabled)return;if(target.dataset.action){actions[target.dataset.action]?.();return;}if(target.dataset.input){document.querySelectorAll('[data-input]').forEach(b=>{const on=b===target;b.classList.toggle('selected',on);b.setAttribute('aria-selected',String(on));});$('photo-input').hidden=target.dataset.input!=='photo';$('text-input').hidden=target.dataset.input!=='text';return;}if(target.dataset.remove!==undefined){state.ingredients.splice(Number(target.dataset.remove),1);dirty();renderIngredients();return;}if(target.dataset.flavor){state.flavor=target.dataset.flavor;profile.flavor=state.flavor;persist();renderFlavors();if(state.generated)generate();else dirty();return;}if(target.dataset.mode){state.mode=target.dataset.mode;state.page=0;if(state.generated)generate();else renderResults();return;}if(target.dataset.favorite){toggleFavorite(target.dataset.favorite);return;}if(target.dataset.loginFavorite){profile.loggedIn=true;persist();closeModal();toggleFavorite(target.dataset.loginFavorite);return;}if(target.dataset.detail){detail(target.dataset.detail);return;}if(target.dataset.replace){replace(target.dataset.replace);return;}if(target.dataset.condition){const c=target.dataset.condition;pendingConditions=pendingConditions.includes(c)?pendingConditions.filter(x=>x!==c):[...pendingConditions,c];renderHealthModal();return;}if(target.dataset.page){state.page+=target.dataset.page==='next'?1:-1;renderResults();return;}if(target.dataset.scenario){scenario(target.dataset.scenario);}});
  document.addEventListener('change',event=>{const t=event.target;if(t.dataset.ingredientName!==undefined){state.ingredients[Number(t.dataset.ingredientName)].name=t.value.trim();dirty();return;}if(t.dataset.ingredientAmount!==undefined){state.ingredients[Number(t.dataset.ingredientAmount)].amount=t.value.trim();dirty();return;}if(t.id==='servings'){changeServings(t.value);return;}if(t.name==='seasoning-mode'){state.seasoningMode=t.value;profile.seasoningMode=t.value;persist();$('seasoning-checks').hidden=t.value!=='check';dirty();return;}if(t.dataset.seasoning){profile.seasonings=[...document.querySelectorAll('[data-seasoning]:checked')].map(x=>x.dataset.seasoning);persist();dirty();return;}if(t.id==='quick-allergies'){profile.allergies=t.value.trim();persist();dirty();return;}if(t.id==='include-others'){state.includeOthers=t.checked;dirty();return;}if(t.id==='browse-buy'){state.allowBuy=t.checked;generate();return;}if(t.id.startsWith('count-')){dirty();return;}if(t.id==='food-upload'||t.id==='camera-upload'){handleUpload(t.files[0]);}});
  $('add-ingredient').addEventListener('submit',e=>{e.preventDefault();const value=$('new-ingredient').value.trim();if(!value)return;if(state.ingredients.length>=24){toast('演示最多支持24种食材');return;}const parsed=E.parseIngredients(value);for(const item of parsed){if(!state.ingredients.some(x=>E.normalize(x.name)===item.name))state.ingredients.push(item);}state.ingredients=state.ingredients.slice(0,24);$('new-ingredient').value='';dirty();renderIngredients();});
  $('camera-trigger').addEventListener('click',e=>{e.preventDefault();e.stopPropagation();$('camera-upload').click();});$('camera-trigger').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('camera-upload').click();}});
  $('condition-input')?.addEventListener('keydown',e=>{if(e.key==='Enter')matchCondition();});
  document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='condition-input'){e.preventDefault();matchCondition();}});
  $('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
  $('modal').addEventListener('close',()=>{if(!$('modal').open)lastModal='';});
  $('upload-icon').innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><rect x="3" y="5" width="18" height="15" rx="3"/><path d="m3 16 5-5 5 5 3-3 5 5M9 5l1-2h4l1 2"/><circle cx="16" cy="10" r="1.5"/></svg>';
  syncSettings();renderIngredients();renderResults();
})();

